package pricing

import "testing"

func TestCartTotal(t *testing.T) {
	tests := []struct {
		name string
		cart Cart
		want int
	}{
		{
			name: "sums price times quantity across items",
			cart: Cart{
				Items: []*Item{
					{Name: "pen", Cents: 150, Qty: 3},
					{Name: "notebook", Cents: 499, Qty: 2},
				},
				Discount: &Discount{Percent: 0},
			},
			want: 1448,
		},
		{
			name: "applies percent discount to the sum",
			cart: Cart{
				Items: []*Item{
					{Name: "pen", Cents: 200, Qty: 5},
				},
				Discount: &Discount{Percent: 10},
			},
			want: 900,
		},
		{
			name: "truncates fractional discount cents in favor of the shop",
			cart: Cart{
				Items:    []*Item{{Name: "mug", Cents: 999, Qty: 1}},
				Discount: &Discount{Percent: 15},
			},
			want: 850,
		},
		{
			name: "empty cart totals zero",
			cart: Cart{Discount: &Discount{Percent: 20}},
			want: 0,
		},
		{
			name: "cart without a discount totals the full sum",
			cart: Cart{
				Items: []*Item{{Name: "pen", Cents: 150, Qty: 2}},
			},
			want: 300,
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := tt.cart.Total(); got != tt.want {
				t.Errorf("Total() = %d, want %d", got, tt.want)
			}
		})
	}
}

func TestApplyDiscount(t *testing.T) {
	tests := []struct {
		name           string
		cents, percent int
		want           int
	}{
		{"zero percent leaves price unchanged", 1000, 0, 1000},
		{"reduces by percent", 1000, 25, 750},
		{"truncates fractional discount cents", 999, 15, 850},
		{"full discount is free", 1000, 100, 0},
		{"percent above 100 never goes below zero", 1000, 150, 0},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := ApplyDiscount(tt.cents, tt.percent); got != tt.want {
				t.Errorf("ApplyDiscount(%d, %d) = %d, want %d", tt.cents, tt.percent, got, tt.want)
			}
		})
	}
}

